    let rows = fixture(config.rows, config.profile);
    let expected = expected_matches(&rows);
    let tmp = tempfile::tempdir().unwrap();
    let mut storage = PartitionManager::open(config.storage(tmp.path())).unwrap();
    for batch in rows.chunks(config.batch_rows) { storage.write_batch(batch).unwrap(); }
    storage.checkpoint().unwrap();
    for partition in storage.sealed_partitions().iter().chain(std::iter::once(storage.hot_partition())) {
        if partition.meta.row_count > 0 { IndexBuilder::build_all_indexes(&partition.meta.path).unwrap(); }
    }
    storage.compact_eligible_segments().unwrap();
    drop(storage);
    let storage = PartitionManager::open(config.storage(tmp.path())).unwrap();
    assert_native(&storage, &expected);
    println!("{}", json!({"kind":"config", "profile":config.profile.name(), "fixture_digest":keccak256(serde_json::to_vec(&rows).unwrap()).to_string(), "rows":config.rows}));
    let predicate = format!("address = '{HOT_ADDRESS}' AND topic0 = '{}'", transfer_topic());
