        ("sql_count", format!("SELECT COUNT(*) AS total FROM logs WHERE {predicate}"), vec![json!({"total":expected.len()})]),
        ("sql_ordered", format!("SELECT block_number, tx_index, log_index FROM logs WHERE {predicate} ORDER BY block_number DESC, tx_index DESC, log_index DESC LIMIT 1000"), expected.iter().rev().take(1000).map(|r|json!({"block_number":r.block_number,"tx_index":r.tx_index,"log_index":r.log_index})).collect()),
    ];
