            let elapsed_ms = start.elapsed().as_secs_f64() * 1000.;
            assert_eq!(result.rows, *wanted);
            println!("{}", json!({"kind":"latency","metric":metric,"iteration":iteration,"elapsed_ms":elapsed_ms}));
        }
    }
    for iteration in 0..31 {
        let barrier = Arc::new(Barrier::new(config.workers + 1));
        let elapsed = std::thread::scope(|scope| {
            let mut handles = Vec::new();
            for _ in 0..config.workers {
                let barrier = barrier.clone();
                let storage = &storage;
                handles.push(scope.spawn(move || { barrier.wait(); execute_log_filter(storage, &filter()).unwrap() }));
            }
            let start = Instant::now(); barrier.wait();
            let results: Vec<_> = handles.into_iter().map(|h|h.join().unwrap()).collect();
            let elapsed = start.elapsed();
            for result in results { assert_eq!(result, expected); }
            elapsed
        });
        if iteration > 0 { println!("{}",json!({"kind":"latency","metric":"concurrent_native_queries","iteration":iteration,"elapsed_ms":elapsed.as_secs_f64()*1000.})); }
    }
